#include HEADER
#include <chrono>
#include <random>
#include <cstdio>
#include <string>
#include <vector>
#include <utility>
#include <limits>
using I=std::int64_t;
constexpr I infinity=std::numeric_limits<I>::max();
using Tree=DynamicLiChaoTree<I,infinity>;
int main(int argc,char**argv) {
 const std::string mode=argc>1?argv[1]:"point";const int n=argc>2?std::stoi(argv[2]):100000;
 std::mt19937_64 rng(789);std::uint64_t sum=0;std::size_t nodes=0;
 const auto start=std::chrono::steady_clock::now();
 for(int rep=0;rep<(n<=64?3000:1);++rep) {
  I width=mode=="wide"?std::numeric_limits<I>::max():I(n)*16;
  Tree tree(0,width);
  for(int i=0;i<n;++i) {
   I l=I(rng()%(std::uint64_t(width)+1));I r=l;
   if(mode=="disjoint"){l=I(i)*16;r=l+15;}
   if(mode=="narrow")r=std::min(width,l+15);
   if(mode=="decreasing"){l=0;r=width;}
   if(mode=="equal"){l=I(rng()%(std::uint64_t(width)+1));r=width;}
   I a=I(rng()%1001)-500,b=I(rng()%200001)-100000;
   if(mode=="decreasing"){a=0;b=-i;}
   if(mode=="equal"){a=0;b=5;}
   if(mode=="wide"){a=0;b=i%100;}
   tree.add_segment(a,b,l,r);
   sum^=std::uint64_t(tree.query(l));
   if(mode=="disjoint" && tree.query(l)!=a*l+b)return 2;
  }
  nodes+=tree.stored_nodes();sum^=std::uint64_t(tree.query(width));
 }
 const auto dt=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();
 std::printf("%jd %ju %zu\n",std::intmax_t(dt),std::uintmax_t(sum),nodes);
}

