#include LI_CHAO_SOURCE
#include <chrono>
#include <cstdio>
#include <random>
#include <string>
#include <vector>
using I=std::int64_t;
using Tree=DynamicLiChaoTree<I,std::numeric_limits<I>::max()>;
int main(int argc,char**argv){
 const std::string mode=argc>1?argv[1]:"random";const int count=mode=="small"?16:8192;
 const I width=mode=="small"?32:1'000'000'000;
 Tree t(-width,width);std::mt19937_64 rng(1781);
 if(mode!="empty")for(int i=0;i<count;++i){const I a=i-count/2;const I b=mode=="random"?static_cast<I>(rng()%1000000000):a*a;t.add_line(a,b);}
 const int queries=1'000'000;std::vector<I> xs(queries);for(auto&x:xs)x=static_cast<I>(rng()%static_cast<std::uint64_t>(2*width+1))-width;
 std::uint64_t check{};using C=std::chrono::steady_clock;
 const auto start=C::now();for(I x:xs)check^=static_cast<std::uint64_t>(t.query(x));const auto middle=C::now();
 for(I x:xs){const auto l=t.query_line(x);if(l)check^=static_cast<std::uint64_t>(l->get(x));else check^=static_cast<std::uint64_t>(std::numeric_limits<I>::max());}const auto end=C::now();
 std::printf("%jd %jd %ju %zu\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(middle-start).count()),static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-middle).count()),static_cast<std::uintmax_t>(check),t.stored_nodes());
}

