#include LI_CHAO_SOURCE
#include <chrono>
#include <cstdio>
#include <string>
using I=std::int64_t;
using Tree=DynamicLiChaoTree<I,std::numeric_limits<I>::max()>;
using Clock=std::chrono::steady_clock;
[[gnu::noinline]] static I observed(const Tree& tree,I x) {
 volatile I value=tree.query(x);return value;
}
static std::int64_t elapsed(Clock::time_point start) {
 return std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();
}
int main(int argc,char**argv) {
 const int count=argc>1?std::stoi(argv[1]):65536;
 const int repeats=count<100?2000:12;
 Tree source(-1'000'000'000,1'000'000'000);
 for(I a=0;a<count;++a)source.add_line(a,a*a);
 const auto nodes=source.stored_nodes();std::uint64_t check=0;
 std::int64_t full=0,partial=0,empty=0;
 for(int i=0;i<repeats;++i) {
  {Tree copy(source);auto start=Clock::now();copy.reserve(nodes*2);full+=elapsed(start);check+=std::uint64_t(observed(copy,-i));}
  {Tree copy(source);copy.reserve(nodes*4);auto start=Clock::now();copy.reserve(nodes*8);partial+=elapsed(start);check+=std::uint64_t(observed(copy,-i));}
  {Tree copy(source);copy.reserve(nodes*4);auto start=Clock::now();copy.clear();copy.reserve(nodes*8);empty+=elapsed(start);check+=std::uint64_t(observed(copy,-i));}
 }
 auto start=Clock::now();
 for(int i=0;i<repeats;++i){Tree copy(source);check+=std::uint64_t(observed(copy,-i));}
 const auto construct=elapsed(start);
 Tree destination(source);destination.reserve(nodes*2);
 start=Clock::now();
 for(int i=0;i<repeats;++i){destination.add_line(0,-i-1);destination=source;check+=std::uint64_t(observed(destination,-i));}
 const auto assign=elapsed(start);
 const int refill_repeats=count<100?2000:3;
 start=Clock::now();
 for(int i=0;i<refill_repeats;++i){destination.clear();for(I a=0;a<count;++a)destination.add_line(a,a*a);check+=std::uint64_t(observed(destination,-i));}
 const auto refill=elapsed(start);
 std::printf("%jd %jd %jd %jd %jd %jd %ju %zu\n",std::intmax_t(full),std::intmax_t(partial),std::intmax_t(empty),std::intmax_t(construct),std::intmax_t(assign),std::intmax_t(refill),std::uintmax_t(check),nodes);
}
